'use strict';
// port of SBPE plugins/version.py: replaces the main menu's version label
// with a pulsing "client v... + SBPE ... by ..." in the bottom left corner
var util = sbpe.util;
var mem = WebBreak.mem;

// the web client is an older build than SBPE's headers; only touch the label
// if the field really points at one
