    stage: null,
    MainMenu: null, GameClient: null, WorldClient: null, ClientWorld: null, WorldView: null,
    overrideW: 0, overrideH: 0,   // fake values to return from XDL_GetWindowSize
    windowW: 0, windowH: 0,
    scaleX: 1, scaleY: 1,
    lastMove: 0,
    manager: null,
